<?php include "../includes/cek_session.php";include "../config/koneksi.php";$title="Laporan Penjualan";include "../includes/header.php";$from=$_GET['from']??date('Y-m-01');$to=$_GET['to']??date('Y-m-d');$sf=mysqli_real_escape_string($koneksi,$from);$st=mysqli_real_escape_string($koneksi,$to);$data=mysqli_query($koneksi,"SELECT t.*,u.nama_lengkap,COALESCE(p.nama_pelanggan,'Pelanggan Umum') pelanggan FROM tb_transaksi t JOIN tb_pengguna u ON u.id_pengguna=t.id_pengguna LEFT JOIN tb_pelanggan p ON p.id_pelanggan=t.id_pelanggan WHERE DATE(t.tanggal) BETWEEN '$sf' AND '$st' ORDER BY t.id_transaksi DESC");$sum=mysqli_fetch_row(mysqli_query($koneksi,"SELECT COALESCE(SUM(total_bayar),0) FROM tb_transaksi WHERE DATE(tanggal) BETWEEN '$sf' AND '$st'"))[0];?>
<div class="page-head"><h1>Laporan Penjualan</h1></div><div class="panel"><form class="filter no-print"><input class="form-control" type="date" name="from" value="<?=$from?>"><input class="form-control" type="date" name="to" value="<?=$to?>"><button class="btn">Tampilkan</button><button type="button" class="btn light" onclick="window.print()">Cetak</button></form><p>Periode: <?=$from?> s/d <?=$to?></p><div class="table-wrap"><table><tr><th>No Transaksi</th><th>Tanggal</th><th>Kasir</th><th>Pelanggan</th><th>Total</th></tr><?php while($t=mysqli_fetch_assoc($data)):?><tr><td><?=htmlspecialchars($t['no_transaksi'])?></td><td><?=htmlspecialchars($t['tanggal'])?></td><td><?=htmlspecialchars($t['nama_lengkap'])?></td><td><?=htmlspecialchars($t['pelanggan'])?></td><td>Rp <?=number_format($t['total_bayar'],0,',','.')?></td></tr><?php endwhile;?></table></div><p class="text-right total">Total Penjualan: Rp <?=number_format($sum,0,',','.')?></p></div><?php include "../includes/footer.php";?>